import numpy as np

N = 26

def construct_packing() -> tuple:
    try:
        centers = np.loadtxt('storage/episteme/base_416_centers.txt')
        radii = np.loadtxt('storage/episteme/base_416_radii.txt')
    except Exception:
        return np.random.rand(N, 2), np.full(N, 0.05)

    # --- Identify Near-Contact Pairs ---
    slacks = []
    for i in range(N):
        for j in range(i + 1, N):
            dist = np.linalg.norm(centers[i] - centers[j])
            slack = dist - (radii[i] + radii[j])
            # Only consider pairs that are not touching but are close
            if slack > 1e-8:
                slacks.append({'pair': (i, j), 'slack': slack})

    slacks.sort(key=lambda x: x['slack'])

    top_5_targets = slacks[:5]

    # --- Save Analysis to Storage ---
    report = ["# Top 5 Near-Contact Pairs for Nudging Experiments\n"]
    report.append("# Pair_i Pair_j Slack\n")
    for target in top_5_targets:
        i, j = target['pair']
        slack_val = target['slack']
        report.append(f"{i} {j} {slack_val:.8f}")

    try:
        with open('storage/episteme/top_5_nudge_targets.txt', 'w') as f:
            f.write("\n".join(report))
    except Exception as e:
        pass

    # Return the base packing to ensure a valid run
    return centers, radii
